/* Topological routing only: published stop order, no inferred GPS or timetables. */
(function(root){'use strict';
function create(data){const stops=Object.fromEntries(data.stops.map(s=>[s.id,s])),routes=Object.fromEntries(data.routes.map(r=>[r.id,r])),adj={};for(const r of data.routes){for(let i=0;i<r.orderedStops.length-1;i++){let a=r.orderedStops[i],b=r.orderedStops[i+1];if(a===b)continue;(adj[a]??=[]).push({to:b,route:r.id,direction:1});(adj[b]??=[]).push({to:a,route:r.id,direction:-1})}}
 const served=id=>data.routes.filter(r=>r.orderedStops.includes(id));
 const preferred=['borella','dematagoda','orugodawatta','town_hall','sethsiripaya','pannipitiya'];
 function find(a,b,banned=new Set()){if(a===b||!stops[a]||!stops[b])return null;let queue=[{stop:a,route:null,dir:0,cost:0,changes:0,path:[]}],seen=new Map();while(queue.length){queue.sort((a,b)=>a.cost-b.cost);let q=queue.shift(),key=q.stop+'|'+q.route+'|'+q.dir;if((seen.get(key)??Infinity)<=q.cost)continue;seen.set(key,q.cost);if(q.stop===b){let legs=[];for(let edge of q.path){let last=legs.at(-1);if(last&&last.routeId===edge.route&&last.direction===edge.direction){last.stopIds.push(edge.to);last.to=edge.to}else legs.push({routeId:edge.route,direction:edge.direction,from:edge.from,to:edge.to,stopIds:[edge.from,edge.to]})}return {from:a,to:b,legs,changes:legs.length-1,stopCount:q.path.length,transfers:legs.slice(0,-1).map(l=>l.to)}}for(const edge of adj[q.stop]||[]){if(q.route===edge.route&&q.dir!==edge.direction)continue;let change=q.route&&q.route!==edge.route;if(change&&banned.has(q.stop))continue;let changes=q.changes+(change?1:0);if(changes>2)continue;let pi=preferred.indexOf(q.stop),cost=q.cost+1+(change?1000+(pi<0?.2:pi*.01):0);queue.push({stop:edge.to,route:edge.route,dir:edge.direction,cost,changes,path:[...q.path,{...edge,from:q.stop}]})}}return null}
 function connections(a,b){let results=[],banned=new Set();for(let i=0;i<4;i++){let p=find(a,b,banned);if(!p)break;let signature=p.legs.map(l=>l.routeId+':'+l.from+':'+l.to).join('|');if(results.some(x=>x.id===signature))break;p.id=signature;results.push(p);if(!p.transfers.length)break;for(const t of p.transfers)banned.add(t)}return results}
 function search(q){q=q.toLocaleLowerCase().trim();return data.stops.filter(s=>Object.values(s.name).some(n=>n.toLocaleLowerCase().includes(q))||s.id.includes(q)).filter(s=>served(s.id).length)}
 return {data,stops,routes,served,connections,search};}
root.createMetroNetwork=create;if(typeof module!=='undefined')module.exports=create;
})(typeof globalThis!=='undefined'?globalThis:this);
